update platform_app_release
   set manifest = #{manifest,jdbcType=LONGVARCHAR},
       objects_json = #{objectsJson,jdbcType=LONGVARCHAR}
 where id = #{id,jdbcType=BIGINT}
   and (manifest is null or trim(manifest) = '')
